100:impl SealedId {
101:    /// Deterministic SID1 bytes: fixed-order bounded fields followed by the
102:    /// SHA-256 integrity seal over `MAGIC || body`.
103:    pub fn seal(&self) -> Result<Vec<u8>, SealedIdError> {
104:        let mut out = Vec::with_capacity(1024);
105:        out.extend_from_slice(MAGIC);
106:        push_string(&mut out, &self.principal_id)?;
107:        push_string(&mut out, &self.principal_kind)?;
108:        push_string(&mut out, &self.session_id)?;
109:        push_string(&mut out, &self.wireguard_pubkey)?;
110:        push_string(&mut out, &self.session_genesis)?;
111:        push_string(&mut out, &self.trace_id)?;
112:        out.extend_from_slice(&self.schema_version.to_le_bytes());
113:        out.extend_from_slice(&self.issued_at.to_le_bytes());
114:        out.extend_from_slice(&self.expires_at.to_le_bytes());
115:        out.extend_from_slice(&self.arrival_timestamp.to_le_bytes());
116:        push_string(&mut out, &self.chain_head_at_arrival)?;
117:        push_string(&mut out, &self.catalog_hash_at_arrival)?;
118:        out.extend_from_slice(&self.head_timestamp_at_arrival.to_le_bytes());
119:        push_string(&mut out, &self.transport_scope)?;
120:        if let Some(nextdns) = &self.nextdns {
121:            nextdns.validate()?;
122:            out.extend_from_slice(NEXTDNS_EXTENSION_TAG);
123:            push_string(&mut out, &nextdns.profile_id)?;
124:            push_string(&mut out, &nextdns.device_name)?;
125:        }
126:        if out.len().saturating_add(SEAL_LEN) > MAX_WIRE_LEN {
127:            return Err(SealedIdError::TooLarge);
128:        }
129:        let seal = Sha256::digest(&out);
130:        out.extend_from_slice(&seal);
131:        Ok(out)
132:    }
133:
134:    /// Decode and verify one exact SID1 envelope.
135:    pub fn open(wire: &[u8]) -> Result<Self, SealedIdError> {
136:        if wire.len() > MAX_WIRE_LEN {
137:            return Err(SealedIdError::TooLarge);
138:        }
139:        if wire.len() < MAGIC.len() + SEAL_LEN || &wire[..MAGIC.len()] != MAGIC {
140:            return Err(SealedIdError::Malformed);
141:        }
142:        let body_end = wire.len() - SEAL_LEN;
143:        let expected = Sha256::digest(&wire[..body_end]);
144:        if expected.as_slice() != &wire[body_end..] {
145:            return Err(SealedIdError::SealMismatch);
146:        }
147:
148:        let mut reader = Reader::new(&wire[MAGIC.len()..body_end]);
149:        let mut sealed = Self {
150:            principal_id: reader.read_string()?,
151:            principal_kind: reader.read_string()?,
152:            session_id: reader.read_string()?,
153:            wireguard_pubkey: reader.read_string()?,
154:            session_genesis: reader.read_string()?,
155:            trace_id: reader.read_string()?,
156:            schema_version: reader.read_u32()?,
157:            issued_at: reader.read_i64()?,
158:            expires_at: reader.read_i64()?,
159:            arrival_timestamp: reader.read_i64()?,
160:            chain_head_at_arrival: reader.read_string()?,
161:            catalog_hash_at_arrival: reader.read_string()?,
162:            head_timestamp_at_arrival: reader.read_i64()?,
163:            transport_scope: reader.read_string()?,
164:            nextdns: None,
165:        };
166:        if !reader.is_consumed() {
167:            if reader.take(NEXTDNS_EXTENSION_TAG.len())? != NEXTDNS_EXTENSION_TAG.as_slice() {
168:                return Err(SealedIdError::Malformed);
169:            }
170:            let nextdns = NextDnsContext {
171:                profile_id: reader.read_string()?,
172:                device_name: reader.read_string()?,
173:            };
174:            nextdns.validate()?;
175:            sealed.nextdns = Some(nextdns);
176:        }
177:        if !reader.is_consumed()
178:            || sealed.principal_id.is_empty()
179:            || sealed.session_id.is_empty()
180:            || sealed.wireguard_pubkey.is_empty()
181:            || sealed.session_genesis.is_empty()
182:            || sealed.trace_id.is_empty()
183:        {
184:            return Err(SealedIdError::Malformed);
185:        }
186:        Ok(sealed)
187:    }
188:
189:    /// Embed the sealed bytes directly into the sled's existing `sealed_id`.
190:    pub fn to_inline_ref(&self) -> Result<String, SealedIdError> {
191:        Ok(format!(
